type RejectOtherPendingBidOffersParams struct {
	SessionID int32 `db:"session_id"`
	ID        int32 `db:"id"`
}

func (q *Queries) RejectOtherPendingBidOffers(ctx context.Context, arg RejectOtherPendingBidOffersParams) ([]BidOffer, error) {
	rows, err := q.db.Query(ctx, rejectOtherPendingBidOffers, arg.SessionID, arg.ID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BidOffer{}
	for rows.Next() {
		var i BidOffer
		if err := rows.Scan(
			&i.ID,
			&i.SessionID,
			&i.DriverID,
			&i.DriverName,
			&i.PlateNumber,
			&i.VehicleType,
			&i.ProposedFare,
			&i.Status,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
